// Shared by build-snapshot.mjs and validate-snapshot.mjs.
//
// Layout (read by src/engine/recipe-store.ts):
//   snapshot/<platform>/index.json   generated by build-snapshot.mjs; never edited by hand
//   snapshot/<platform>/r<N>.json    the recipes: the ONE source of truth
//
// parseRecipe is imported straight from the TypeScript source: Node >= 22.18 strips types by
// default and src/engine/recipe.ts has only type-only imports, so no build or tsx is needed.

import { createHash } from 'node:crypto';
import { readdir, readFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const RECIPE_FILE_RE = /^r(\d+)\.json$/;

export async function loadParseRecipe() {
  const mod = await import(join(ROOT, 'src', 'engine', 'recipe.ts'));
  return mod.parseRecipe;
}

export function snapshotDirFromArgv() {
  return resolve(process.argv[2] ?? join(ROOT, 'snapshot'));
}

export function sha256(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

/** Platform directories and stray top-level files of a snapshot directory. */
export async function listSnapshot(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  return {
    platforms: entries
      .filter((e) => e.isDirectory())
      .map((e) => e.name)
      .sort(),
    files: entries.filter((e) => !e.isDirectory()).map((e) => e.name),
  };
}

/** `r<N>.json` files of one platform directory, in revision order. */
export async function recipeFiles(platformDir) {
  const names = (await readdir(platformDir)).filter((n) => RECIPE_FILE_RE.test(n));
  return names.sort(
    (a, b) => Number(RECIPE_FILE_RE.exec(a)[1]) - Number(RECIPE_FILE_RE.exec(b)[1]),
  );
}

export async function readBytes(path) {
  return readFile(path);
}

/** A readable reason from a parseRecipe (RecipeError) or JSON failure. */
export function describeError(err) {
  if (err && Array.isArray(err.violations)) return err.violations.join('; ');
  return err instanceof Error ? err.message : String(err);
}
